<script setup lang="ts">
import { computed } from 'vue'
import type { SubjectId } from '../model'
import type { SubjectWeek } from '../curriculum/types'
import type { LessonSection } from '../focus'
import { effectiveStatus, statusNames } from '../curriculum/types'
import { sourcesForSubject } from '../curriculum/sources'
import OriginalProblem from './OriginalProblem.vue'

const props = defineProps<{ week: number; subject: SubjectId; lesson?: SubjectWeek; completed: string[]; section?: LessonSection | 'sources' }>()
const emit = defineEmits<{ complete: [id: string, checked: boolean] }>()
const status = computed(() => effectiveStatus(props.lesson))
const references = computed(() => sourcesForSubject(props.subject, props.lesson?.sourceIds))
const checkpoints = [{ kind: 'knowledge', label: '理解知识点与考查方式' }, { kind: 'example', label: '独立尝试例题并核对解析' }, { kind: 'practice', label: '完成独立练习并订正' }, { kind: 'retest', label: '完成复测并核对标准' }]
const show = (section: string) => !props.section || props.section === section
const retestTasks = computed(() => {
  const normalize = (value: string) => value.replace(/\s+/g, '').trim()
  const prompt = props.lesson?.retest.problem?.prompt
  return (props.lesson?.retest.tasks || []).filter(task => !prompt || normalize(task) !== normalize(prompt))
})
const available = (kind: string) => kind === 'knowledge' ? !!props.lesson?.knowledge.length : kind === 'example' ? !!props.lesson?.examples.length : kind === 'practice' ? !!props.lesson?.exercises.length : !!props.lesson?.retest.tasks.length
</script>

<template>
  <section class="lesson-content">
    <div v-if="!section" class="panel lesson-heading"><div class="path-heading"><div><p class="eyebrow">WEEK {{ String(week).padStart(2,'0') }}</p><h2>{{ lesson?.title || '本学科内容待补充' }}</h2></div><span class="outline-badge" :class="`status-${status}`">{{ statusNames[status] }}</span></div><p v-if="status !== 'complete'" class="content-warning">{{ status === 'outline' ? '这里目前只有周纲，尚未提供完整知识讲解、例题、练习与复测。空缺不会自动补成题目。' : '本周本学科内容尚未接入，没有提供完整讲解或题目。' }}</p><p v-else class="help">教学编排、题目及解析为原创；明确标源的古诗文为公版原典。往年题只提供经过核验的官方评析索引。</p><p v-if="lesson?.trainingScope" class="content-warning">{{ lesson.trainingScope }}</p></div>
    <section v-if="show('prepare') && (lesson?.trainingMode || lesson?.audioStatus || lesson?.listeningMasteryStatus)" class="panel listening-notice"><h2>听力文字预训练 · 非音频</h2><p class="content-warning">本站未提供音频。阅读脚本、文字作答或本页打卡不代表听力已经完成或真实听辨已达标；需另行隐藏脚本进行真实听辨验证。</p><p v-if="lesson.trainingMode" class="math-text">{{ lesson.trainingMode === 'text-script-only' ? '当前训练方式：文字脚本预训练' : lesson.trainingMode }}</p><p v-if="lesson.audioStatus">音频状态：{{ lesson.audioStatus }}</p><p v-if="lesson.listeningMasteryStatus">听辨状态：{{ lesson.listeningMasteryStatus }}</p></section>
    <section v-if="show('prepare') && (lesson?.materialNote || lesson?.safetyScope)" class="panel material-notice"><h2>材料与使用边界</h2><p v-if="lesson.materialNote" class="math-text">{{ lesson.materialNote }}</p><p v-if="lesson.safetyScope" class="math-text">{{ lesson.safetyScope }}</p></section>
    <section v-if="show('prepare')" class="panel"><h2>目标与前置</h2><div class="lesson-two-columns"><div><h3>本周目标</h3><ul v-if="lesson?.goals.length"><li v-for="goal in lesson.goals" :key="goal">{{ goal }}</li></ul><p v-else class="pending-copy">目标待补充。</p></div><div><h3>先确认这些基础</h3><ul v-if="lesson?.prerequisites.length"><li v-for="pre in lesson.prerequisites" :key="pre">{{ pre }}</li></ul><p v-else class="pending-copy">前置要求待补充。</p></div></div></section>
    <section v-if="show('knowledge')" class="panel"><h2>知识讲解</h2><template v-if="lesson?.knowledge.length"><article v-for="block in lesson.knowledge" :key="block.title" class="knowledge-block"><h3>{{ block.title }}</h3><p v-for="paragraph in block.paragraphs" :key="paragraph" class="math-text">{{ paragraph }}</p><ul v-if="block.keyPoints?.length"><li v-for="point in block.keyPoints" :key="point">{{ point }}</li></ul></article></template><p v-else class="pending-copy">知识正文待补充；周纲不代表已提供完整讲解。</p></section>
    <section v-if="show('sources')" class="panel"><h2>考查方式与考点</h2><ul v-if="lesson?.examPoints.length"><li v-for="point in lesson.examPoints" :key="point">{{ point }}</li></ul><p v-else class="pending-copy">考查方式待补充。</p></section>
    <section v-if="show('examples')" class="panel"><h2>原创例题</h2><template v-if="lesson?.examples.length"><OriginalProblem v-for="problem in lesson.examples" :key="problem.id" :problem="problem" label="原创基础例题（非高考原题）" reveal-label="展开例题解析"/></template><p v-else class="pending-copy">原创例题与解析待补充。</p></section>
    <section v-if="show('practice')" class="panel"><h2>独立练习</h2><p class="help">先独立作答，再展开答案订正。页面不提供智能评分。</p><template v-if="lesson?.exercises.length"><OriginalProblem v-for="problem in lesson.exercises" :key="problem.id" :problem="problem" label="原创独立练习（非高考原题）" reveal-label="完成后核对答案与解析"/></template><p v-else class="pending-copy">独立练习与答案待补充。</p></section>
    <section v-if="show('retest')" class="panel"><h2>复测与掌握标准</h2><ul v-if="retestTasks.length"><li v-for="task in retestTasks" :key="task" class="math-text">{{ task }}</li></ul><p v-else-if="!lesson?.retest.problem" class="pending-copy">复测安排待补充。</p><OriginalProblem v-if="lesson?.retest.problem" :problem="lesson.retest.problem" label="原创复测题（非高考原题）" reveal-label="复测完成后查看解析"/><h3>自行核对的标准</h3><p v-if="lesson?.progressionNote" class="help">{{ lesson.progressionNote }}</p><p v-if="lesson?.masteryStatus" class="content-warning">{{ lesson.masteryStatus }}</p><p v-if="lesson?.writingMasteryStatus" class="content-warning">{{ lesson.writingMasteryStatus }}</p><ul v-if="lesson?.retest.criteria.length"><li v-for="criterion in lesson.retest.criteria" :key="criterion">{{ criterion }}</li></ul><p v-else class="pending-copy">掌握标准待补充，不会自动判断已掌握。</p><p class="help">未达到标准可以继续停留在本学习周，订正后再测。小测不能换算为预测高考分或录取保证。</p><template v-if="lesson?.commonErrors?.length"><h3>易错提醒</h3><ul><li v-for="error in lesson.commonErrors" :key="error">{{ error }}</li></ul></template></section>
    <section v-if="show('diagnostic') && lesson?.diagnosticTest" class="panel diagnostic-panel"><h2>{{ lesson.diagnosticTest.title }}</h2><p class="original-label">原创诊断测评（非历年真题） · 共 {{ lesson.diagnosticTest.totalPoints }} 分</p><p class="content-warning">{{ lesson.diagnosticTest.scopeNote }}</p><p class="help">这是教学诊断，不提供智能评分，不换算高考分数或录取概率。请独立作答后再展开答案和逐点评分。</p><p v-for="instruction in lesson.diagnosticTest.instructions" :key="instruction" class="math-text">{{ instruction }}</p><OriginalProblem v-for="problem in lesson.diagnosticTest.questions" :key="problem.id" :problem="problem" label="原创诊断题（非历年真题）" reveal-label="诊断完成后查看答案与逐点评分"/><h3>如何理解本次结果</h3><p v-for="note in lesson.diagnosticTest.scoreInterpretation" :key="note" class="math-text">{{ note }}</p><h3>按失分项返回前置</h3><ul><li v-for="item in lesson.diagnosticTest.remediationMap" :key="item.questionId">{{ item.questionId }}：{{ item.guidance.join('；') }}</li></ul></section>
    <section v-if="show('retest') && lesson?.pendingChecklist?.length" class="panel pending-checklist"><h2>尚需独立验证的能力</h2><p class="content-warning">课程正文齐全不等于已掌握。以下项目不会因阅读范文、打卡或诊断分数达到建议阈值而自动通过。</p><ul><li v-for="item in lesson.pendingChecklist" :key="item">{{ item }}</li></ul></section>
    <section v-if="show('sources') && lesson?.contentReferences?.length" class="panel content-references"><h2>原典与知识核验资料</h2><p class="help">这些链接用于原典出处或教学原理核验，不是历年真题来源。</p><article v-for="source in lesson.contentReferences" :key="source.url" class="source-card"><h3><a :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }} ↗</a></h3><p>{{ source.note }}</p></article></section>
    <section v-if="show('sources')" class="panel source-panel"><h2>往年真题考点参考</h2><p class="content-warning">查看官方评析；这里不是原题全文题库，没有核验的题干、选项、答案或真题详解不会呈现。</p><article v-for="source in references" :key="source.id" class="source-card"><span class="original-label">往年真题考点参考（查看官方评析）</span><h3><a :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }} ↗</a></h3><p>{{ source.year }} 年 · {{ source.paper }} · {{ source.publisher }}</p><p>{{ source.scopeNote }}</p><ul v-if="source.items?.length"><li v-for="item in source.items.filter(n => !n.subject || n.subject === source.subject || n.subject === ({physics:'物理',chemistry:'化学',biology:'生物学'} as Record<string,string>)[subject])" :key="`${item.subject}-${item.number}`">{{ item.subject ? item.subject + ' · ' : '' }}题号 {{ item.number }}：{{ item.topic }}<span v-if="item.prerequisites?.length">；前置：{{ item.prerequisites.join('、') }}</span></li></ul><p class="help">{{ source.foundationUse }}</p></article><p v-if="!references.length" class="pending-copy">本学科可靠往年题来源待补充，不编造题号、题干或答案。</p><p class="help">题号核验不等于原题全文核验。浙江选考和全国理综均不能标作河南选择性考试。第三方材料不受本项目 MIT 许可覆盖。</p></section>
    <section v-if="!section" class="panel lesson-checkpoints"><h2>本学科学习打卡</h2><p class="help">只勾选实际完成的步骤。内容待补充的步骤不可标记为已完成，打卡不会自动增加学习时长。<span v-if="lesson?.audioStatus">听力相关课次的打卡仅表示文字预训练；真实听辨仍待验证。</span></p><label v-for="checkpoint in checkpoints" :key="checkpoint.kind" class="check-row"><input type="checkbox" :disabled="!available(checkpoint.kind)" :checked="completed.includes(`w${week}-${subject}-${checkpoint.kind}`)" @change="emit('complete', `w${week}-${subject}-${checkpoint.kind}`, ($event.target as HTMLInputElement).checked)"/><span>我已完成 · {{ checkpoint.label }}<small v-if="!available(checkpoint.kind)">内容待补充</small></span></label></section>
  </section>
</template>
